package com.bananalab.lite;
import java.util.*;
/** Reversible paired contact geometry. The scene remains the source for preview and export. */
final class KissMotion{
 static float envelope(float t){return t<.32f?Scene.ease(t/.32f):t>.74f?Scene.ease((1-t)/.26f):1;}
 static int active(SceneDraft d,String name,float time){if(d==null)return -1;int slot=Math.min(ObjectTransfer.beats(d)-1,(int)(Math.max(0,Math.min(1,time))*ObjectTransfer.beats(d)));for(int i=0;i<d.actions.size();i++)if(d.slot(i)==slot&&d.actions.get(i).equals("besa")&&(d.cast.get(d.actors.get(i)).name.equals(name)||d.recipient(i).equals(name)))return i;return -1;}
 static int direction(SceneDraft d,String name,int step){SceneDraft.Actor from=d.cast.get(d.actors.get(step)),to=d.get(d.recipient(step));Map<String,Float> positions=ScenePositions.at(d,(d.slot(step)+.01f)/ObjectTransfer.beats(d));float dx=positions.get(to.name)-positions.get(from.name);int direction=dx>=0?1:-1;return name.equals(from.name)?direction:-direction;}
 static float[] mouth(SceneDraft.Actor a,int direction){int kind=Math.max(0,PixelGenerator.type(a.kind));float fx=FaceAnchor.CENTERS[kind][0],fy=FaceAnchor.CENTERS[kind][1];float x=32+(fx-32)*.78f+8;if(direction<0)x=64-x;return new float[]{x,fy+8};}
 static float[] base(SceneDraft d,String name,float time){SceneDraft.Actor a=d.get(name);float s=ActorGeometry.scale(a,d.cast.size());return new float[]{ScenePositions.at(d,time).get(name),80-14*s+a.y-67,s*Appearance.width(a.look),s*Appearance.height(a.look),0};}
 static float[] pose(SceneDraft d,String name,float time){int i=active(d,name,time);if(i<0)return null;String from=d.cast.get(d.actors.get(i)).name,to=d.recipient(i);float[] own=base(d,name,time),a=base(d,from,time),b=base(d,to,time),ma=mouth(d.get(from),direction(d,from,i)),mb=mouth(d.get(to),direction(d,to,i));float[] wa=ActorGeometry.world(ma[0],ma[1],a),wb=ActorGeometry.world(mb[0],mb[1],b);float phase=Math.max(0,Math.min(1,time))*ObjectTransfer.beats(d)-d.slot(i),e=envelope(Math.max(0,Math.min(1,phase))),x=(wa[0]+wb[0])/2+(name.equals(from)?-1:1)*direction(d,from,i)*JavaLive.gap/2,y=(wa[1]+wb[1])/2;float[] anchor=name.equals(from)?wa:wb;own[0]+=(x-anchor[0])*e;own[1]+=(y-anchor[1])*e;return own;}
 static String problem(SceneDraft d){for(int i=0;i<d.actions.size();i++)if(d.actions.get(i).equals("besa")||d.actions.get(i).equals("recibebeso")){String actor=d.cast.get(d.actors.get(i)).name,to=d.recipient(i);int pairs=0;for(int j=0;j<d.actions.size();j++)if(d.slot(j)==d.slot(i)&&d.actions.get(j).equals(d.actions.get(i).equals("besa")?"recibebeso":"besa")&&d.cast.get(d.actors.get(j)).name.equals(to)&&d.recipient(j).equals(actor))pairs++;if(pairs!=1)return "El beso necesita dos personajes distintos con acciones coincidentes.";Map<String,Float> positions=ScenePositions.at(d,(d.slot(i)+.01f)/ObjectTransfer.beats(d));if(positions.get(actor)<12||positions.get(actor)>88||positions.get(to)<12||positions.get(to)>88)return "Un personaje está fuera del encuadre; hacelo entrar antes del beso.";}return null;}
}
